const KEY='shipment-word-rules-v3';
function seed(){let t=now(),make=(id,customer,temp,city,district,addr,h)=>({id,source:id,customer,temp,city,district,address:addr,phone:'138****2688',created:t-24*H,due:t+h*H,status:'ready',items:[{sku:temp==='cold'?'SKU-C001':'SKU-N001',name:temp==='cold'?'冷冻调理食品':'常温礼盒',qty:20},{sku:'SKU-P002',name:'配套包装',qty:20}]});let orders=[make('SO-001','上海悦集商贸','normal','上海市','闵行区','申长路1688号',96),make('SO-002','上海悦集商贸','normal','上海市','闵行区','申长路1688号',100),make('SO-003','杭州优选供应链','cold','杭州市','余杭区','仓前街道128号',72),make('SO-004','南京星禾零售','normal','南京市','江宁区','天元东路88号',30),make('SO-005','苏州汇选商贸','cold','苏州市','工业园区','星湖街88号',18)];let plan={id:'PL-DEMO-001',orderIds:['SO-003'],customer:orders[2].customer,temp:'cold',city:'杭州市',district:'余杭区',address:orders[2].address,created:t-6*H,due:orders[2].due,status:'published',version:1,createdBy:'计划部 · 张敏',publishedAt:t-5*H,warehouse:true,warehouseName:'杭州优选收货仓',weight:20,boxes:10,length:50,width:40,height:30,payer:'公司承担',note:'入仓前电话联系收货人，确认预约时段。',product:'sfCold',quote:{product:'sfCold',name:'顺丰冷运 · 大件标快',total:null,bill:200,vol:200,divisor:3000,transit:null,pending:['折扣与最低收费顺序待确认','入仓费重量口径待确认','线路时效未配置'],rows:[['运输费','待确认'],['入仓规则','0.2元/kg，最低100元、最高800元']],source:'Word计费规则 / 顺丰冷运.xlsx'},logs:[fmt(t-5*H)+' · 计划部发布演示计划 V1，报价与时效待确认']};orders[2].status='occupied';return{orders,plans:[plan],seq:6,config:{process:8,buffer:4,warn:12,rounding:'pending',kyMode:'pending',sfMode:'pending',coldFormula:'pending',discountFloor:'pending',entryBasis:'pending',ztoEntry:'pending',sfCap:'pending',ztoCap:'pending',transit:{}}}}
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed()}catch{state=seed()}let role='planner',page='plans',searchText='',filter='all',selected=new Set(),wizard=null;
function planner(){return role==='planner'}function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('浏览器未允许本地存储，请保持页面打开')}}function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(window.tt);window.tt=setTimeout(()=>$('toast').hidden=true,3200)}
function badge(s,c=''){return `<span class="tag ${c}">${esc(s)}</span>`}function duration(ms){let n=Math.floor(Math.abs(ms)/60000);return(Math.floor(n/1440)?Math.floor(n/1440)+'天 ':'')+Math.floor(n/60)%24+'小时 '+n%60+'分'}function countdown(t){return(t<now()?'已超时 ':'还剩 ')+duration(t-now())}
function showModal(title,sub,body,foot){$('modalTitle').textContent=title;$('modalSub').textContent=sub;$('modalBody').innerHTML=body;$('modalFoot').innerHTML=foot||'<span></span><button onclick="closeModal()">关闭</button>';if(!$('modal').open)$('modal').showModal();$('modalBody').scrollTop=0}function closeModal(){$('modal').close()}
function readLabel(p){return !p.viewedVersion?'待查看':p.viewedVersion<p.version?'更新待查看':'已查看'}function cutoff(p){return p.quote?.transit?p.due-(p.quote.transit+(p.configSnapshot||state.config).buffer)*H:null}function warning(p){let t=cutoff(p);if(p.status==='cancelled')return{t:'已取消',c:''};if(!t)return{t:'时效待确认',c:'warn'};return t<now()?{t:'发货截止已超时',c:'bad'}:t-now()<state.config.warn*H?{t:'临近发货截止',c:'warn'}:{t:'时效正常',c:'good'}}
function setSearch(v){searchText=v;let pos=document.activeElement.selectionStart;render();let el=document.querySelector('.filters input');el?.focus();if(el&&pos!=null)el.setSelectionRange(pos,pos)}function setFilter(v){filter=v;render()}
function ordersView(){let rows=state.orders.filter(o=>(o.id+o.customer+o.source).includes(searchText));return `<div class="between title"><div><h1>订单拆合单</h1><div class="muted">合单需同客户、同地址、同温层；保留最早下单时间与最早到货要求。</div></div><button class="primary" onclick="startPlan()">创建发货计划</button></div><div class="panel"><div class="between panelhead"><div class="row filters"><input aria-label="搜索订单" placeholder="搜索订单 / 客户" value="${esc(searchText)}" oninput="setSearch(this.value)"><button ${selected.size<2?'disabled':''} onclick="mergeOrders()">合并订单</button><button ${selected.size!==1?'disabled':''} onclick="splitOrder()">拆分订单</button></div><small>已选 ${selected.size} 个</small></div><div class="tablewrap"><table><thead><tr><th>选择</th><th>订单 / 来源</th><th>客户 / 收货</th><th>商品 / 温层</th><th>下单 / 到货要求</th><th>状态</th></tr></thead><tbody>${rows.map(o=>`<tr><td><input type="checkbox" aria-label="选择 ${o.id}" ${o.status!=='ready'?'disabled':''} ${selected.has(o.id)?'checked':''} onchange="pick('${o.id}',this.checked)"></td><td>${esc(o.id)}<small>${esc(o.source)}</small></td><td>${esc(o.customer)}<small>${esc(o.city+o.district+o.address)}</small></td><td>${badge(o.temp==='cold'?'冷运':'常温')}<small>${o.items.map(i=>esc(i.name)+'×'+i.qty).join('；')}</small></td><td>${fmt(o.created)}<small>到货 ${fmt(o.due)}</small><small>${countdown(o.due)}</small></td><td>${badge({ready:'待计划',occupied:'已占用',processed:'已拆合',shipped:'已发货'}[o.status],o.status==='ready'?'good':'')}</td></tr>`).join('')}</tbody></table></div></div>`}
function pick(id,v){v?selected.add(id):selected.delete(id);render()}function compatible(list){let o=list[0];return list.every(x=>x.customer===o.customer&&x.city===o.city&&x.district===o.district&&x.address===o.address&&x.temp===o.temp)}
function mergeOrders(){if(!planner())return;let list=state.orders.filter(o=>selected.has(o.id)&&o.status==='ready');if(list.length<2||!compatible(list)){toast('请选择同客户、同地址、同温层的待计划订单');return}showModal('确认合并订单','合并后商品数量守恒，保留来源订单',`<p>${list.map(o=>esc(o.id)).join(' ＋ ')}</p><p>要求到货取最早值：${fmt(Math.min(...list.map(o=>o.due)))}</p>`,`<button onclick="closeModal()">返回</button><button class="primary" onclick="confirmMerge()">确认合并</button>`)}
function confirmMerge(){if(!planner())return;let list=state.orders.filter(o=>selected.has(o.id)&&o.status==='ready');if(list.length<2||!compatible(list))return;let items=[];list.forEach(o=>o.items.forEach(i=>{let x=items.find(x=>x.sku===i.sku);x?x.qty+=i.qty:items.push({...i})}));state.orders.push({...list[0],id:'MG-'+state.seq++,source:list.map(o=>o.source).join(' / '),items,created:Math.min(...list.map(o=>o.created)),due:Math.min(...list.map(o=>o.due))});list.forEach(o=>o.status='processed');selected.clear();save();closeModal();render();toast('合单完成，可创建计划')}
function splitOrder(){if(!planner())return;let o=state.orders.find(o=>selected.has(o.id)&&o.status==='ready');if(!o)return;showModal('拆分订单',o.id+' · 分为A、B两个订单',`<div class="grid">${o.items.map((i,n)=>`<div class="field"><label for="split-${n}">${esc(i.name)}，总量 ${i.qty}，A订单数量</label><input id="split-${n}" type="number" min="0" max="${i.qty}" value="${Math.ceil(i.qty/2)}"><small>B订单为剩余数量</small></div>`).join('')}</div><p id="error" class="err" role="alert"></p>`,`<button onclick="closeModal()">返回</button><button class="primary" onclick="confirmSplit('${o.id}')">确认拆分</button>`)}
