const same=(a,b)=>String(a).replace(/市$/,'')===String(b).replace(/市$/,'');
function cities(){return [...new Set([...RATE_DB.sfCold,...RATE_DB.kyLand].map(r=>r[1]))].sort((a,b)=>a.localeCompare(b,'zh'))}function districts(city){return [...new Set([...RATE_DB.sfDelivery,...RATE_DB.ztoDelivery].filter(r=>same(r[1],city)).map(r=>r[2]))].sort((a,b)=>a.localeCompare(b,'zh'))}
function roundWeight(w){return state.config.rounding==='ceil'?Math.ceil(w):w}function clamp(v,min,max){return Math.min(Math.max(v,min),max)}
function quoteProducts(w){let gross=w.weight*w.boxes,volume=w.length*w.width*w.height*w.boxes,config=state.config;return PRODUCTS.filter(p=>p.temp===w.temp).map(p=>{let vol=volume/p.divisor,bill=p.id==='zto'?Math.ceil(Math.max(gross,vol)):roundWeight(Math.max(gross,vol)),pending=[],rows=[],transport=null,delivery=0,entry=w.warehouse&&p.temp==='normal'?60:0,rate=null,transit=Number(config.transit[p.id])||null,support=true;let route=(RATE_DB[p.id==='zto'?'ztoPort':p.id]||[]).find(r=>same(r[1],w.city));
if(!route){pending.push('未找到该目的城市的合作报价，请人工询价')}else if(p.temp==='normal'){let mode=p.company==='ky'?config.kyMode:config.sfMode;if(mode==='pending')pending.push('起重与首重适用方式待确认');if(config.rounding==='pending')pending.push('重量进位方式待确认');let charge=mode==='first50'?Math.max(bill,50):Math.max(bill,route[3]||50),first=mode==='first50'?50:1;rate=route[5+(charge<=100?0:charge<=300?1:charge<=500?2:charge<=1000?3:4)];let ref=route[2]+Math.max(0,charge-first)*rate;if(route[4]!=null)ref=Math.max(ref,route[4]);if(mode!=='pending'&&config.rounding!=='pending'){bill=charge;transport=ref}rows.push(['运输算法',`首重${route[2]}元 ＋（计费重－首重重量）×${rate}元/kg`],['报价表起重',route[3]+'kg'+(route[4]!=null?'；最低运费'+route[4]+'元':'')]);if(w.warehouse)entry=60;
}else if(p.company==='sf'){let cuts=p.id==='sfCold'?[200,500]:[1000,3000],i=bill<=cuts[0]?0:bill<=cuts[1]?1:2;rate=route[3+i];let coeff=i===0?0:route[i===1?6:7],raw=bill*rate+coeff;rows.push(['阶梯运输参考',`${bill.toFixed(2)}×${rate}＋${Number(coeff.toFixed(6))}；最低收费${route[2]}元`],['协议折扣','仅运输费×0.62，配送费不打折；不计提货费']);if(config.coldFormula==='pending')pending.push('Word首重通式与Excel阶梯累计的适用口径待确认');if(config.discountFloor==='pending')pending.push('0.62折扣与最低收费先后顺序待确认');if(config.rounding==='pending')pending.push('重量进位方式待确认');if(config.coldFormula==='progressive'&&config.discountFloor!=='pending'&&config.rounding!=='pending')transport=config.discountFloor==='before'?Math.max(route[2],raw)*.62:Math.max(route[2],raw*.62);
if(p.id==='sfPort'){let r=RATE_DB.sfDelivery.find(r=>same(r[1],w.city)&&r[2]===w.district);if(!r){delivery=null;pending.push('未匹配到收货区县配送费')}else if(r[7]!=='Y'){support=false;delivery=null;pending.push('该区县配送标记为不支持，需人工确认承运')}else if(bill>6000){delivery=null;pending.push('6吨以上配送封顶规则待确认')}else if(config.sfCap==='pending'){delivery=null;pending.push('配送封顶重量区间待确认')}else delivery=clamp(bill*r[3],r[4],bill<=2000?r[5]:r[6]);rows.push(['到港配送规则',r?`${r[3]}元/kg；最低${r[4]}元；2T封顶${r[5]}元，6T封顶${r[6]}元`:'区县未匹配'])}
if(w.warehouse){if(config.entryBasis==='pending'){entry=null;pending.push('入仓费采用实际重或计费重待确认')}else entry=clamp(.2*(config.entryBasis==='actual'?gross:bill),100,800)}
}else{let i=bill<=1000?0:bill<=3000?1:2;rate=route[3+i];transport=Math.round(Math.max(route[2],bill*rate));rows.push(['港到港',`${bill}kg×${rate}元/kg，最低${route[2]}元；金额四舍五入`]);let r=RATE_DB.ztoDelivery.find(r=>same(r[1],w.city)&&r[2]===w.district);if(!r){delivery=null;pending.push('未匹配到收货区县配送费')}else if(r[3]===0||r[4]>r[5]){delivery=null;pending.push('区县配送报价异常，需人工核价')}else if(bill>2000&&config.ztoCap==='pending'){delivery=null;pending.push('超过2吨的配送封顶规则待确认')}else delivery=bill<=2000?clamp(bill*r[3],r[4],r[5]):Math.max(bill*r[3],r[4]);rows.push(['港到门',r?`${r[3]}元/kg；最低${r[4]}元；2T封顶${r[5]}元`:'区县未匹配']);if(w.warehouse){if(config.entryBasis==='pending'||config.ztoEntry==='pending'){entry=null;pending.push('中通入仓重量口径及不足一吨计费待确认')}else{let wt=config.entryBasis==='actual'?gross:bill;entry=(config.ztoEntry==='proportional'?wt/1000:Math.ceil(wt/1000))*100}}}
if(!transit)pending.push('合作资料未给出线路时效，需人工确认');let total=[transport,delivery,entry].every(Number.isFinite)&&!pending.some(s=>!s.includes('时效'))?transport+delivery+entry:null;let manual=w.product===p.id&&Number(w.manualTotal)>0&&w.manualSource?.trim();if(manual){total=Number(w.manualTotal);if(Number(w.manualHours)>0)transit=Number(w.manualHours);pending=pending.filter(s=>s.includes('时效'));if(transit)pending=[];rows.push(['人工确认',w.manualSource]);}let arrive=transit?Math.max(now()+config.process*H,w.plannedShip?new Date(w.plannedShip).getTime():0)+(transit+config.buffer)*H:null,onTime=arrive!=null&&arrive<=w.due;rows.push(['运输费',money(transport)],['配送费',delivery===0?'不另计':money(delivery)],['入仓费',!w.warehouse?'不入仓':money(entry)]);return {...p,product:p.id,vol,gross,bill,transport,delivery,entry,rate,rows,pending,total,transit,arrive,onTime,support,manual:!!manual,source:p.source,ready:support&&Number.isFinite(total)&&!!transit,onTimeText:arrive?(onTime?'预计满足到货要求':'预计晚到 '+duration(arrive-w.due)):'预计到货待确认'}}).sort((a,b)=>(a.total??Infinity)-(b.total??Infinity))}
function optionField(key,label,choices){return `<div class="field"><label for="cfg-${key}">${label}</label><select id="cfg-${key}">${choices.map(([v,t])=>`<option value="${v}" ${state.config[key]===v?'selected':''}>${t}</option>`).join('')}</select></div>`}
function rulesView(){return `<div class="between title"><div><h1>物流计费规则</h1><div class="muted">业务规则以 Word 为准，线路与区县单价取 Excel；保留待确认条件。</div></div><button onclick="resetAsk()">重置演示数据</button></div><div class="notice"><b>规则优先级已锁定：Word ＞ Excel冲突条款。</b><br>跨越入仓统一60元/票/地址，不使用Excel的100元；中通入仓不套用Excel中与Word未统一的500元封顶。未选择的待确认口径不会自动生效。</div><div class="panel section"><div class="panelhead"><h2>合作物流与业务规则</h2><small>来源：《物流计费明细.docx》；当前线路均按所提供的马鞍山始发报价使用</small></div><div class="tablewrap"><table class="rules"><thead><tr><th>温层 / 合作物流</th><th>物流产品</th><th>体积重系数</th><th>运输与配送</th><th>入仓费</th></tr></thead><tbody><tr><td>常温 · 跨越</td><td>陆运件 / 省内次日</td><td>8000</td><td>按线路及重量段匹配</td><td>60元/票/地址</td></tr><tr><td>常温 · 顺丰</td><td>重货</td><td>8000</td><td>按线路及重量段匹配</td><td>60元/票/地址</td></tr><tr><td>冷运 · 顺丰</td><td>大件标快</td><td>3000</td><td>运输费×0.62<br>不计配送费、提货费</td><td rowspan="2">0.2元/kg<br>最低100元、最高800元</td></tr><tr><td>冷运 · 顺丰</td><td>大件到港</td><td>3000</td><td>运输费×0.62＋配送费<br>不计提货费</td></tr><tr><td>冷运 · 中通</td><td>冷链</td><td>3300</td><td>港到港＋港到门</td><td>100元/吨<br>不足一吨及重量口径待确认</td></tr></tbody></table></div><div class="footer">体积重 = 长×宽×高（cm）÷系数；实际重和体积重取大计费。一个计划对应一个收货地址、一票。</div></div><form onsubmit="saveConfig(event)"><div class="grid section"><div class="card full"><h2>待确认计费口径</h2><p class="muted">以下项目Word没有明确完整参数。由计划部确认后再选择；更改仅用于新的报价，历史计划保留快照。</p><div class="grid">${optionField('kyMode','跨越起重 / 首重适用方式',[['pending','待确认，不自动计算总价'],['first1','已确认：首重1kg，起重作为最低计费重量'],['first50','已确认：起重50kg作为首重重量']])}${optionField('sfMode','顺丰常温起重 / 首重适用方式',[['pending','待确认，不自动计算总价'],['first50','已确认：50kg首重，超出后按区间单价'],['first1','已确认：首重1kg，起重作为最低计费重量']])}${optionField('rounding','顺丰 / 跨越重量进位',[['pending','待确认'],['ceil','已确认：向上进位至1kg'],['exact','已确认：按原始重量计算']])}${optionField('coldFormula','顺丰冷运运输算法',[['pending','待确认：Word首重通式与Excel阶梯参数'],['progressive','已确认：使用Excel阶梯累计及速算系数，不另加首重']])}${optionField('discountFloor','顺丰冷运最低收费与0.62折扣',[['pending','待确认'],['before','已确认：先执行最低收费，再乘0.62'],['after','已确认：折后仍执行原最低收费']])}${optionField('entryBasis','顺丰冷运 / 中通入仓费用重量',[['pending','待确认'],['actual','已确认：实际重量'],['bill','已确认：该物流计费重量']])}${optionField('ztoEntry','中通不足一吨的入仓费',[['pending','待确认'],['proportional','已确认：按实际吨数比例收费'],['ceil','已确认：不足一吨按一吨收费']])}${optionField('sfCap','顺丰到港区县配送封顶',[['pending','待确认'],['ranges','已确认：≤2T用2T封顶，2–6T用6T封顶；>6T待确认']])}${optionField('ztoCap','中通超过2吨的配送封顶',[['pending','待确认'],['uncapped','已确认：2吨以上按单价及最低收费，不应用2T封顶']])}</div></div><div class="card"><h2>时效与预警</h2><div class="grid">${[['process','仓库处理（小时）'],['buffer','安全缓冲（小时）'],['warn','截止前预警（小时）']].map(([k,t])=>`<div class="field"><label for="cfg-${k}">${t}</label><input id="cfg-${k}" type="number" min="0" max="720" required value="${state.config[k]}"></div>`).join('')}</div><p class="source">最晚发货＝客户到货要求－运输时长－安全缓冲。最晚备货再减仓库处理时长。</p></div><div class="card"><h2>合作线路时效补充</h2><p class="muted">资料未提供完整时效。以下为人工确认参数，仅用于本原型；正式应用应按线路配置。</p><div class="grid">${PRODUCTS.map(p=>`<div class="field"><label for="hours-${p.id}">${p.name}（小时）</label><input id="hours-${p.id}" type="number" min="1" max="720" value="${state.config.transit[p.id]||''}" placeholder="待确认"></div>`).join('')}</div></div></div><div class="row section"><button class="primary" type="submit">保存已确认口径</button><span id="configResult" role="status" class="muted">保留“待确认”即可暂不启用对应计算。</span></div></form><div class="panel"><div class="between panelhead"><h2 style="margin:0">合作线路价格查询</h2><button onclick="routePreview()">选择城市与产品查询</button></div><div class="footer">已内置提供的城市干线与区县配送数据，不引用外部价格。跨越报价表执行日期为2025-05-24，继续使用前请核实有效性。</div></div>`}
function saveConfig(e){e.preventDefault();if(!planner())return;let keys=['kyMode','sfMode','rounding','coldFormula','discountFloor','entryBasis','ztoEntry','sfCap','ztoCap'];keys.forEach(k=>state.config[k]=$('cfg-'+k).value);for(let k of ['process','buffer','warn'])state.config[k]=Number($('cfg-'+k).value);for(let p of PRODUCTS)state.config.transit[p.id]=Number($('hours-'+p.id).value)||null;save();$('configResult').textContent='已保存。新的物流比价将使用这些口径；历史费用不变。';toast('计费口径与时效配置已保存')}
function routePreview(){if(!planner())return;showModal('查询合作线路报价','原始Excel数据查询，不代表已确认完整费用',`<div class="grid section"><div><label for="routeProduct">物流产品</label><select id="routeProduct" onchange="updateRoute()">${PRODUCTS.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></div><div><label for="routeCity">收货城市</label><select id="routeCity" onchange="updateRoute()">${cities().map(c=>`<option ${c==='上海市'?'selected':''}>${esc(c)}</option>`).join('')}</select></div></div><div id="routeInfo"></div>`);updateRoute()}
function updateRoute(){let id=$('routeProduct').value,city=$('routeCity').value,p=PRODUCTS.find(p=>p.id===id),r=RATE_DB[id==='zto'?'ztoPort':id].find(r=>same(r[1],city));if(!r){$('routeInfo').innerHTML='<div class="notice warn">未匹配到城市报价。请人工询价，不能按0元处理。</div>';return}let info=id==='zto'?[['最低运输费',r[2]+'元'],['0–1T / 1–3T / 3T以上（元/kg）',r.slice(3).join(' / ')]]:p.temp==='normal'?[['首重价格',r[2]+'元'],['起重',r[3]+'kg'],['最低运输费',r[4]==null?'表中未单列':r[4]+'元'],['(1,100] / (100,300] / (300,500] / (500,1000] / (1000,+∞)（元/kg）',r.slice(5).join(' / ')]]:[['最低运输费',r[2]+'元'],[id==='sfCold'?'0–200 / 200–500 / 500以上kg（元/kg）':'0–1 / 1–3 / 3以上吨（元/kg）',r.slice(3,6).join(' / ')],['速算系数',r.slice(6).map(v=>+v.toFixed(6)).join(' / ')]];let districtRows=id==='sfPort'?RATE_DB.sfDelivery.filter(r=>same(r[1],city)):id==='zto'?RATE_DB.ztoDelivery.filter(r=>same(r[1],city)):[];$('routeInfo').innerHTML=`<div class="card section"><h3>马鞍山市 → ${esc(city)} · ${p.name}</h3>${info.map(([k,v])=>`<p>${esc(k)}：<b>${esc(v)}</b></p>`).join('')}<small>来源：${esc(p.source)}</small></div>${districtRows.length?`<h3>区县配送费用</h3><div class="tablewrap"><table><thead><tr><th>区县</th><th>元/kg</th><th>最低收费</th><th>2T封顶</th>${id==='sfPort'?'<th>6T封顶</th><th>配送</th>':''}</tr></thead><tbody>${districtRows.map(r=>`<tr><td>${esc(r[2])}</td><td>${r[3]}</td><td>${r[4]}</td><td>${r[5]}</td>${id==='sfPort'?`<td>${r[6]}</td><td>${r[7]==='Y'?'支持':'不支持 / 待确认'}</td>`:''}</tr>`).join('')}</tbody></table></div>`:''}`}
function resetAsk(){if(!planner())return;showModal('重置演示数据','仅影响当前浏览器','<p>清除本原型的计划、拆合单结果及已确认口径，恢复初始演示数据。</p>','<button onclick="closeModal()">保留数据</button><button class="danger" onclick="resetData()">确认重置</button>')}
function resetData(){if(!planner())return;state=seed();save();selected.clear();closeModal();render();toast('已恢复初始演示数据')}
// 两阶段职责：计划部下达发货需求；仓库选择物流并保存费用估算。
function warehouse(){return role==='warehouse'}
function switchRole(v){role=v;closeModal();go('plans')}
function migrateWorkflow(){if(state.workflowVersion===2)return;state.plans.forEach(p=>{p.legacyQuote=p.quote||null;p.packageSeed={weight:p.weight||20,boxes:p.boxes||10,length:p.length||50,width:p.width||40,height:p.height||30};p.estimate=null;for(let k of ['quote','product','manualTotal','manualHours','manualSource','riskAck','reason','weight','boxes','length','width','height'])delete p[k];p.logs.push(fmt(now())+' · 已切换职责流程：发货计划由计划部下达，物流估价待仓库处理');});state.workflowVersion=2;save()}
function estimateStatus(p){if(!p.estimate)return'待选物流';if(p.estimate.planVersion!==p.version)return'需重新估价';return p.estimate.status==='confirmed'?'已估价':'估价草稿'}
function activeQuote(p){return p.status==='published'&&p.estimate?.status==='confirmed'&&p.estimate.planVersion===p.version?p.estimate.quote:null}
cutoff=function(p){let q=activeQuote(p);return q?.transit?p.due-(q.transit+(p.estimate.configSnapshot||state.config).buffer)*H:null};
warning=function(p){if(p.status==='cancelled')return{t:'已取消',c:''};if(p.due<now())return{t:'到货要求已超时',c:'bad'};let t=cutoff(p);if(!t)return{t:'待仓库确认物流时效',c:'warn'};return t<now()?{t:'发货截止已超时',c:'bad'}:t-now()<state.config.warn*H?{t:'临近发货截止',c:'warn'}:{t:'时效正常',c:'good'}};
function go(v){if(planner()&&v==='rules'||warehouse()&&v==='orders')return;page=v;searchText='';filter='all';selected.clear();render()}
function render(){migrateWorkflow();document.querySelectorAll('.nav').forEach(n=>{n.hidden=planner()?n.id==='nav-rules':n.id==='nav-orders';n.classList.toggle('active',n.id==='nav-'+page)});document.querySelector('.planner').hidden=planner();$('role').value=role;$('crumb').textContent=(planner()?'计划部':'仓库')+' / '+{plans:planner()?'发货需求计划':'物流选择与费用估算',orders:'订单拆合单',rules:'物流计费规则'}[page];$('app').innerHTML=page==='plans'?plansView():page==='orders'?ordersView():rulesView()}
function plansView(){let all=state.plans.filter(p=>planner()||p.publishedAt),pub=all.filter(p=>p.status==='published'),rows=all.filter(p=>(p.id+p.customer+p.orderIds.join('')).includes(searchText)&&(filter==='all'||filter==='draft'&&p.status==='draft'||filter==='pending'&&p.status==='published'&&estimateStatus(p)!=='已估价'||filter==='done'&&p.status==='published'&&!!activeQuote(p)||filter==='urgent'&&p.status==='published'&&warning(p).c==='bad'||filter==='cancelled'&&p.status==='cancelled')).sort((a,b)=>(cutoff(a)||a.due)-(cutoff(b)||b.due));let stats=planner()?[['已下达计划',pub.length,'仓库负责物流与费用'],['草稿',all.filter(p=>p.status==='draft').length,'仅计划部可见'],['仓库待处理',pub.filter(p=>estimateStatus(p)!=='已估价').length,'待选物流或重新估价'],['仓库已估价',pub.filter(p=>estimateStatus(p)==='已估价').length,'结果可查看']]:[['待选物流',pub.filter(p=>!p.estimate).length,'先核实包裹，再选择物流'],['需重新估价',pub.filter(p=>p.estimate&&p.estimate.planVersion!==p.version).length,'计划已更新，原估价失效'],['估价草稿',pub.filter(p=>estimateStatus(p)==='估价草稿').length,'可继续完善'],['已估价',pub.filter(p=>estimateStatus(p)==='已估价').length,'保留费用及规则快照']];return `<div class="between title"><div><h1>${planner()?'发货需求计划':'物流选择与费用估算'}</h1><div class="muted">${planner()?'只下达发货需求，物流选择、包裹核实和费用估算由仓库完成。':'接收计划部下达的需求，核实包裹，选择物流并保存预估费用。'}</div></div>${planner()?'<button class="primary" onclick="startPlan()">＋ 新建发货计划</button>':''}</div><div class="cards">${stats.map(([t,n,s])=>`<div class="card"><small>${t}</small><div class="stat">${n}</div><small>${s}</small></div>`).join('')}</div><div class="notice"><b>计划部下计划 → 仓库选物流、估价格</b><br>${planner()?'填写商品、数量、收货信息、到货时间和入仓要求即可下达，不需要选择物流或填写运费。':'计划需求不可修改；按Word口径计算费用，在满足到货要求的完整报价中优先低价。'}计划更新后原估价保留为历史记录，需仓库重新估价。</div><div class="panel"><div class="between panelhead"><div class="row filters"><input aria-label="搜索计划" placeholder="搜索计划 / 客户 / 订单" value="${esc(searchText)}" oninput="setSearch(this.value)"><select aria-label="筛选计划" onchange="setFilter(this.value)">${[['all','全部计划'],...(planner()?[['draft','草稿']]:[]),['pending','仓库待处理'],['done','仓库已估价'],['urgent','时效已超时'],['cancelled','已取消']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></div><small>共 ${rows.length} 个计划</small></div><div class="tablewrap"><table><thead><tr><th>计划 / 制定人</th><th>客户 / 发货需求</th><th>到货要求 / 剩余时间</th><th>仓库物流 / 预估费用</th><th>计划 / 估价状态</th><th>操作</th></tr></thead><tbody>${rows.map(p=>{let q=activeQuote(p),s=estimateStatus(p);return `<tr><td class="nowrap"><button class="link" onclick="detail('${p.id}')">${p.id}</button><small>${esc(p.createdBy)} · V${p.version}</small><small>创建 ${fmt(p.created)}</small></td><td>${esc(p.customer)} ${badge(p.temp==='cold'?'冷运':'常温')}<small>${esc(p.city+p.district)} · ${p.warehouse?'需入仓':'普通配送'}</small><small>${p.orderIds.length}个订单 / ${p.orderIds.reduce((n,id)=>n+state.orders.find(o=>o.id===id).items.reduce((s,i)=>s+i.qty,0),0)}件</small></td><td class="nowrap">${fmt(p.due)}<small>${countdown(p.due)}</small><small>${badge(warning(p).t,warning(p).c)}</small></td><td>${q?esc(q.name):p.estimate?'原方案待重新确认':'待计划部完善'}<small><b>${q?money(q.total):'尚未估价'}</b></small>${q?'<small>估价人 '+esc(p.estimate.createdBy)+'</small>':''}</td><td>${badge(p.status==='draft'?'草稿':p.status==='published'?'已下达':'已取消',p.status==='published'?'good':'')}<small>${p.status==='draft'?'仓库不可见':badge(s,s==='已估价'?'good':'warn')}</small>${p.viewedAt?'<small>仓库查看 '+fmt(p.viewedAt)+'</small>':''}</td><td class="nowrap">${warehouse()&&p.status==='published'?`<button class="primary" onclick="startEstimate('${p.id}')">${s==='已估价'?'调整物流估价':s==='估价草稿'?'继续估价':'选物流 / 估价'}</button>`:''}<button class="link" onclick="detail('${p.id}')">查看详情</button>${planner()&&p.status!=='cancelled'?`<button class="link" onclick="editPlan('${p.id}')">${p.status==='draft'?'继续编辑':'修改需求'}</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">暂无符合条件的计划。<br><button onclick="searchText=\'\';filter=\'all\';render()">清除筛选</button></td></tr>'}</tbody></table></div><div class="footer">职责独立：计划部维护需求，仓库维护物流估价 · 预估费用不代表实际结算 · 本地数据用于原型演示</div></div>`}
function startPlan(){if(!planner())return;wizard={mode:'plan',step:1,orderIds:[...selected].filter(id=>state.orders.find(o=>o.id===id)?.status==='ready'),warehouse:false,warehouseName:'',payer:'公司承担',note:'',plannedShip:''};showWizard()}
function chosen(){return state.orders.filter(o=>wizard.orderIds.includes(o.id))}function adopt(){let a=chosen(),o=a[0];Object.assign(wizard,{customer:o.customer,temp:o.temp,city:o.city,district:o.district,address:o.address,due:Math.min(...a.map(o=>o.due))})}
function chooseOrder(id,v){if(!planner())return;v?wizard.orderIds.push(id):wizard.orderIds=wizard.orderIds.filter(x=>x!==id);showWizard()}
function showWizard(){if(wizard?.mode==='estimate'){if(warehouse())showEstimate();return}if(!planner())return;let body='<div class="steps">'+['选择订单','填写发货需求','确认下达'].map((s,i)=>`<span class="${wizard.step===i+1?'active':''}">${i+1}. ${s}</span>`).join('')+'</div>';if(wizard.step===1){let list=state.orders.filter(o=>o.status==='ready'||wizard.orderIds.includes(o.id));body+='<div class="notice">选择同客户、同地址、同温层的订单。计划部无需确认物流价格。</div>'+list.map(o=>`<label class="quote ${wizard.orderIds.includes(o.id)?'selected':''}"><div class="quotehead"><input type="checkbox" ${wizard.orderIds.includes(o.id)?'checked':''} onchange="chooseOrder('${o.id}',this.checked)"><div class="info"><b>${o.id} · ${esc(o.customer)}</b> ${badge(o.temp==='cold'?'冷运':'常温')}<small style="display:block">${esc(o.city+o.district+o.address)}<br>原始下单 ${fmt(o.created)}</small></div><div>要求到货<br>${fmt(o.due)}</div></div></label>`).join('');if(!list.length)body+='<div class="empty">暂无未占用的订单。</div>'}
if(wizard.step===2)body+=`<div class="notice">${esc(wizard.customer)} ${badge(wizard.temp==='cold'?'冷运':'常温')}<br>马鞍山市主仓 → ${esc(wizard.city+wizard.district+wizard.address)}<br>客户要求到货 ${fmt(wizard.due)} · ${countdown(wizard.due)}</div><div class="grid section"><div class="field"><label for="plannedShip">期望发货时间（可选）</label><input id="plannedShip" type="datetime-local" value="${esc(wizard.plannedShip||'')}" oninput="wizard.plannedShip=this.value"><small>仓库按期望时间安排；是否满足到货要求由仓库选物流后判断。</small></div><div class="field"><label for="warehouse">是否要求入仓</label><select id="warehouse" onchange="wizard.warehouse=this.value==='yes';showWizard()"><option value="no" ${!wizard.warehouse?'selected':''}>否，普通配送</option><option value="yes" ${wizard.warehouse?'selected':''}>是，配送至客户指定仓库</option></select></div>${wizard.warehouse?`<div class="field"><label for="warehouseName">入仓仓库名称 *</label><input id="warehouseName" value="${esc(wizard.warehouseName||'')}" oninput="wizard.warehouseName=this.value"></div><div class="field"><label for="payer">费用承担方</label><select id="payer" onchange="wizard.payer=this.value"><option ${wizard.payer==='公司承担'?'selected':''}>公司承担</option><option ${wizard.payer==='客户承担'?'selected':''}>客户承担</option></select></div>`:''}</div><label for="note">发货与入仓要求</label><textarea id="note" rows="3" placeholder="如预约时间、收货时段、卸货、联系要求" oninput="wizard.note=this.value">${esc(wizard.note||'')}</textarea><div class="notice" style="margin-top:16px">物流公司、包裹重量体积及预估运费由仓库处理，无需在此填写。</div>`;
if(wizard.step===3)body+=`<div class="notice">下达后进入“待仓库选物流”状态。仓库核实包裹并估价后，结果将回显到计划详情。</div>${requestSummary(wizard)}<p class="muted">本次下达不选择承运商，不产生预估运费。</p>`;
body+='<p id="error" class="err" role="alert"></p>';showModal(wizard.editId?'修改发货需求':'新建发货计划','计划部：只填写发货需求，仓库负责物流选择及价格估算',body,`<button onclick="${wizard.step===1?'closeModal()':'previousStep()'}">${wizard.step===1?'取消':'上一步'}</button><div class="row">${wizard.step>1&&!wizard.editingPublished?'<button onclick="saveDraft()">保存草稿</button>':''}<button class="primary" onclick="${wizard.step===3?'publishPlan()':'nextStep()'}">${wizard.step===3?wizard.editingPublished?'下达更新需求':'下达计划给仓库':'下一步'}</button></div>`)}
function requestSummary(p){return `<div class="grid section"><div class="card"><h3>收货与时效要求</h3><p>${esc(p.customer)} ${badge(p.temp==='cold'?'冷运':'常温')}<br>${esc(p.city+p.district+p.address)}<br>客户要求到货：${fmt(p.due)}<br>期望发货：${p.plannedShip?fmt(new Date(p.plannedShip).getTime()):'未指定，由仓库安排'}</p><p>${p.warehouse?'入仓仓库：'+esc(p.warehouseName):'普通配送'}<br>${esc(p.note||'无其他配送要求')}</p></div><div class="card"><h3>商品与订单</h3>${p.orderIds.map(id=>{let o=state.orders.find(o=>o.id===id);return `<p><b>${esc(id)}</b><small style="display:block">来源 ${esc(o.source)} · 下单 ${fmt(o.created)}</small>${o.items.map(i=>esc(i.name)+' × '+i.qty).join('<br>')}</p>`}).join('')}</div></div>`}
function validStep(){if(wizard.mode==='estimate')return validEstimate();let err='';if(wizard.step===1&&(!chosen().length||!compatible(chosen())))err='请选择同客户、同地址、同温层的订单。';if(wizard.step===2){if(wizard.warehouse&&!wizard.warehouseName?.trim())err='请填写入仓仓库名称。';else if(wizard.plannedShip&&new Date(wizard.plannedShip).getTime()>wizard.due)err='期望发货时间不能晚于客户要求到货时间。'}if(err){$('error').textContent=err;return false}return true}
function nextStep(){if(wizard.mode==='estimate'?!warehouse():!planner())return;if(!validStep())return;if(wizard.mode==='plan'&&wizard.step===1)adopt();wizard.step++;showWizard()}function previousStep(){wizard.step--;showWizard()}
function persistPlan(status){if(!planner())return;let old=state.plans.find(p=>p.id===wizard.editId),id=old?.id||'PL-'+new Date().toLocaleDateString('sv-SE').replaceAll('-','')+'-'+String(state.seq++).padStart(3,'0'),version=old?old.version+(status==='published'&&old.publishedAt?1:0):1;let p={id,orderIds:[...wizard.orderIds],customer:wizard.customer,temp:wizard.temp,city:wizard.city,district:wizard.district,address:wizard.address,due:wizard.due,warehouse:wizard.warehouse,warehouseName:wizard.warehouseName,payer:wizard.payer,note:wizard.note,plannedShip:wizard.plannedShip,status,version,createdBy:old?.createdBy||'计划部 · 张敏',created:old?.created||now(),publishedAt:status==='published'?now():null,viewedVersion:old?.viewedVersion,viewedAt:old?.viewedAt,estimate:old?.estimate||null,estimateHistory:old?.estimateHistory||[],logs:[...(old?.logs||[]),fmt(now())+' · 计划部'+(status==='published'?'下达需求 V'+version+'，待仓库选择物流并估价':'保存草稿')]};if(old){old.orderIds.filter(id=>!p.orderIds.includes(id)).forEach(id=>state.orders.find(o=>o.id===id).status='ready');state.plans[state.plans.indexOf(old)]=p}else state.plans.unshift(p);p.orderIds.forEach(id=>state.orders.find(o=>o.id===id).status='occupied');save();selected.clear();page='plans';closeModal();render();return p}
function saveDraft(){if(!planner()||wizard.mode!=='plan'||wizard.editingPublished)return;if(wizard.step===2&&!validStep())return;adopt();persistPlan('draft');toast('草稿已保存，仓库不可见')}
function publishPlan(){if(!planner()||wizard.mode!=='plan')return;if(wizard.step!==3)return;let p=persistPlan('published');if(!p)return;detail(p.id);toast('计划已下达，等待仓库选择物流和估价')}
function editPlan(id){if(!planner())return;let p=state.plans.find(p=>p.id===id);if(!p||p.status==='cancelled')return;wizard={...JSON.parse(JSON.stringify(p)),mode:'plan',editId:id,editingPublished:!!p.publishedAt,step:2};showWizard()}
function startEstimate(id){if(!warehouse())return;let p=state.plans.find(p=>p.id===id);if(!p||p.status!=='published')return;let current=p.estimate?.planVersion===p.version?p.estimate:null;wizard={...JSON.parse(JSON.stringify(p)),...(current?.package||p.packageSeed||{weight:20,boxes:10,length:50,width:40,height:30}),mode:'estimate',planId:id,planVersion:p.version,step:1,product:current?.quote?.id||current?.product||'',manualTotal:current?.manualTotal||'',manualHours:current?.manualHours||'',manualSource:current?.manualSource||'',reason:current?.reason||'',riskAck:false};showWizard()}
function invalidate(){wizard.product='';wizard.manualTotal='';wizard.manualSource='';wizard.manualHours='';wizard.reason='';wizard.riskAck=false}
function selectProduct(id){if(!warehouse()||wizard.mode!=='estimate')return;wizard.product=id;wizard.manualTotal='';wizard.manualSource='';wizard.manualHours='';wizard.reason='';wizard.riskAck=false;showWizard()}
function showEstimate(){let body='<div class="steps">'+['核实包裹','选择物流并估价','确认仓库方案'].map((s,i)=>`<span class="${wizard.step===i+1?'active':''}">${i+1}. ${s}</span>`).join('')+'</div>';if(wizard.step===1)body+=`<div class="notice">计划 ${wizard.planId} · V${wizard.planVersion} · ${esc(wizard.customer)}<br>${esc(wizard.city+wizard.district+wizard.address)} · ${wizard.warehouse?'需入仓：'+esc(wizard.warehouseName):'普通配送'}<br>客户要求到货 ${fmt(wizard.due)} · ${countdown(wizard.due)}</div><h3>仓库核实包裹</h3><p class="muted">填写实际打包信息。原型按同规格多箱、一地址一票汇总估价；这些数据不改变计划部下达的商品和数量。</p><div class="grid three section">${[['weight','单箱毛重（kg）'],['boxes','箱数'],['length','单箱长（cm）'],['width','单箱宽（cm）'],['height','单箱高（cm）']].map(([k,t])=>`<div class="field"><label for="${k}">${t} *</label><input id="${k}" type="number" min="0.1" step="${k==='boxes'?1:.1}" value="${wizard[k]}" oninput="wizard.${k}=Number(this.value);invalidate()"></div>`).join('')}</div><div class="notice">温层、收货信息、入仓要求及客户到货时间由计划部维护。发现不一致时请联系计划部修改需求。</div>`;
if(wizard.step===2){let qs=quoteProducts(wizard),best=qs.find(q=>q.ready&&q.onTime);if(!wizard.product)wizard.product=(best||qs.find(q=>q.support)||qs[0]).id;let current=quoteProducts(wizard).find(q=>q.id===wizard.product);body+=`<div class="notice"><b>仓库选择物流并估算价格</b> · ${wizard.temp==='cold'?'仅比较冷运产品':'仅比较常温产品'}<br>按Word计费规则和合作线路报价，在满足到货要求的完整报价中优先低价；未知费用不按0元处理。</div>${qs.map(q=>`<div class="quote ${q.id===wizard.product?'selected':''}"><div class="quotehead"><input type="radio" name="product" aria-label="选择${q.name}" ${q.id===wizard.product?'checked':''} onchange="selectProduct('${q.id}')"><div class="info"><b>${q.name}</b> ${best?.id===q.id?badge('可比报价最低','good'):''}<small style="display:block">实际重${q.gross.toFixed(2)}kg · 体积重${q.vol.toFixed(2)}kg（系数${q.divisor}） · 计费重${q.bill.toFixed(2)}kg</small><small>${q.onTimeText}${q.manual?' · 人工核价':''}</small></div><div class="price">${money(q.total)}<small style="display:block">${badge(q.ready?q.onTime?'时效符合':'晚到风险':'待确认',q.ready&&q.onTime?'good':'warn')}</small></div></div><details class="breakdown"><summary>费用明细与来源</summary>${q.rows.map(([k,v])=>`<p>${esc(k)}：${esc(v)}</p>`).join('')}<small>${esc(q.source)}；Word业务口径</small></details>${q.pending.length?'<div class="breakdown" style="color:var(--amber)">'+q.pending.map(esc).join('；')+'</div>':''}</div>`).join('')}<div class="card section"><h3>所选：${current.name} · 人工核价补充</h3><p class="muted">自动报价条件不足时，由仓库补充已确认的总价、运输时长与依据。也可保存估价草稿，稍后继续处理。</p><div class="grid three"><div class="field"><label for="manualTotal">确认总价（含运输、配送、入仓，元）</label><input id="manualTotal" type="number" min=".01" step=".01" value="${wizard.manualTotal}" oninput="wizard.manualTotal=this.value"></div><div class="field"><label for="manualHours">确认运输时长（小时）</label><input id="manualHours" type="number" min="1" value="${wizard.manualHours}" oninput="wizard.manualHours=this.value"></div><div class="field"><label for="manualSource">报价及确认依据</label><input id="manualSource" value="${esc(wizard.manualSource)}" oninput="wizard.manualSource=this.value" placeholder="联系人、日期或报价单号"></div></div><button style="margin-top:12px" onclick="showWizard()">应用确认信息并重新比价</button></div><label for="reason">物流选择说明（人工报价或非推荐方案必填）</label><input id="reason" value="${esc(wizard.reason)}" oninput="wizard.reason=this.value"><label class="check" style="margin-top:16px"><input type="checkbox" ${wizard.riskAck?'checked':''} onchange="wizard.riskAck=this.checked">如存在晚到风险，已反馈计划部并确认后续安排</label>`}
if(wizard.step===3){let q=quoteProducts(wizard).find(q=>q.id===wizard.product);body+=`<div class="notice ${q.onTime?'':'warn'}">${q.onTime?'方案预计满足客户到货要求。':'方案存在晚到风险，已记录仓库反馈。'}保存后计划部可查看物流与预估费用。</div><div class="grid section"><div class="card"><h3>仓库选定物流</h3><p>${q.name} · ${wizard.temp==='cold'?'冷运':'常温'}<br>${wizard.boxes}箱，总实际重${(wizard.weight*wizard.boxes).toFixed(2)}kg<br>${wizard.warehouse?'入仓：'+esc(wizard.warehouseName):'普通配送'}</p><div class="metric">${money(q.total)}</div><small>${q.manual?'人工核价：'+esc(wizard.manualSource):'按Word规则自动估算'}</small></div><div class="card"><h3>发货时效</h3><p>运输时长：${q.transit}小时<br>最晚发货：${fmt(wizard.due-(q.transit+state.config.buffer)*H)}<br>要求到货：${fmt(wizard.due)}</p><p>选择说明：${esc(wizard.reason||'满足时效的可比报价最低')}</p></div></div><p class="muted">本次仅保存物流方案与预估费用，不改变计划部商品、数量、地址和到货要求；不代表已实际发货。</p>`}
body+='<p id="error" class="err" role="alert"></p>';showModal('仓库选物流 / 估价 · '+wizard.planId,'仓库负责：核实包裹 → 选择物流 → 估算价格',body,`<button onclick="${wizard.step===1?'closeModal()':'previousStep()'}">${wizard.step===1?'取消':'上一步'}</button><div class="row"><button onclick="saveEstimate(true)">保存估价草稿</button><button class="primary" onclick="${wizard.step===3?'saveEstimate(false)':'nextStep()'}">${wizard.step===3?'保存物流与预估费用':'下一步'}</button></div>`)}
function validEstimate(){let err='';if(['weight','boxes','length','width','height'].some(k=>!Number.isFinite(wizard[k])||wizard[k]<=0)||!Number.isInteger(wizard.boxes))err='请填写正数重量和尺寸，箱数须为正整数。';if(!err&&wizard.step>=2){let qs=quoteProducts(wizard),q=qs.find(q=>q.id===wizard.product),best=qs.find(q=>q.ready&&q.onTime);if(!q?.ready)err='报价或时效待确认，请补充人工核价信息或保存估价草稿。';else if(!q.onTime&&!wizard.riskAck)err='该方案可能晚到，请反馈计划部并确认风险。';else if((q.manual||best?.id!==q.id)&&!wizard.reason.trim())err='请填写人工报价或选择非推荐物流的说明。'}if(err){$('error').textContent=err;return false}return true}
function saveEstimate(draft){if(!warehouse()||wizard.mode!=='estimate')return;let p=state.plans.find(p=>p.id===wizard.planId);if(!p||p.status!=='published'||p.version!==wizard.planVersion){$('error').textContent='计划已更新或取消，请重新打开最新计划。';return}if(!draft&&!validEstimate())return;let q=wizard.product?quoteProducts(wizard).find(q=>q.id===wizard.product):null;if(p.estimate){p.estimateHistory||=[];p.estimateHistory.push(JSON.parse(JSON.stringify(p.estimate)))}p.estimate={status:draft?'draft':'confirmed',planVersion:p.version,createdBy:'仓库 · 李强',updatedAt:now(),package:Object.fromEntries(['weight','boxes','length','width','height'].map(k=>[k,wizard[k]])),product:wizard.product,quote:q?JSON.parse(JSON.stringify(q)):null,manualTotal:wizard.manualTotal,manualHours:wizard.manualHours,manualSource:wizard.manualSource,reason:wizard.reason,riskAck:wizard.riskAck,configSnapshot:JSON.parse(JSON.stringify(state.config))};p.logs.push(fmt(now())+' · 仓库'+(draft?'保存估价草稿':'选择'+q.name+'，预估费用'+money(q.total))+'，对应需求 V'+p.version);save();closeModal();render();toast(draft?'估价草稿已保存，可继续完善':'仓库物流方案与预估费用已保存');if(!draft)detail(p.id)}
function detail(id){let p=state.plans.find(p=>p.id===id);if(!p||warehouse()&&!p.publishedAt)return;if(warehouse()&&p.status==='published'&&p.viewedVersion!==p.version){p.viewedVersion=p.version;p.viewedAt=now();p.logs.push(fmt(now())+' · 仓库查看需求 V'+p.version);save();render()}let e=p.estimate,q=activeQuote(p),w=warning(p);let logistics=q?`<div class="grid section"><div class="card"><h3>仓库物流方案</h3><p>${esc(q.name)} · ${e.package.boxes}箱<br>实际重${(e.package.weight*e.package.boxes).toFixed(2)}kg · 体积重${q.vol.toFixed(2)}kg<br>计费重${q.bill.toFixed(2)}kg · 体积重系数${q.divisor}<br>估价人：${esc(e.createdBy)} · ${fmt(e.updatedAt)}</p><p>选择说明：${esc(e.reason||'符合时效的可比报价最低')}</p></div><div class="card"><h3>仓库预估费用 ${money(q.total)}</h3>${q.rows.map(([k,v])=>`<p>${esc(k)}：${esc(v)}</p>`).join('')}<small>${q.manual?'人工确认总价，分项仅供参考。':'按保存时规则快照估算。'}<br>运输时长${q.transit}小时 · 最晚发货${fmt(cutoff(p))}<br>来源：${esc(q.source)}</small></div></div>`:`<div class="notice warn">${estimateStatus(p)==='需重新估价'?'计划部已更新需求，原物流估价失效，等待仓库按最新版本重新处理。':e?.status==='draft'?'仓库正在完善包裹、物流和费用，当前为估价草稿。':'等待仓库核实包裹、选择物流并估算价格。'}${e?.quote?'<br>历史 / 草稿方案：'+esc(e.quote.name)+' · '+money(e.quote.total)+'（不可作为当前费用）':''}</div>`;showModal('计划详情 · '+id,(planner()?'计划部：维护发货需求，查看仓库估价':'仓库：查看需求，维护物流估价')+' · V'+p.version,`<div class="notice ${p.status==='cancelled'?'bad':w.c==='bad'?'bad':''}">${p.status==='cancelled'?'该计划已取消，请停止按此计划安排。':countdown(p.due)+'到客户要求到货时间 · '+w.t}<br>下达人：${esc(p.createdBy)} · 创建${fmt(p.created)} · 下达${fmt(p.publishedAt)}</div>${requestSummary(p)}<h3>仓库处理结果 ${badge(estimateStatus(p),q?'good':'warn')}</h3>${logistics}<div class="card"><h3>需求与物流处理记录</h3><div class="timeline">${p.logs.map(s=>'<p>'+esc(s)+'</p>').join('')}</div></div>`,`<div>${planner()&&p.status!=='cancelled'?`<button class="danger" onclick="cancelAsk('${id}')">取消计划</button>`:''}</div><div class="row">${p.status!=='cancelled'?(planner()?`<button class="primary" onclick="editPlan('${id}')">${p.status==='draft'?'继续编辑':'修改需求'}</button>`:`<button class="primary" onclick="startEstimate('${id}')">${q?'调整物流估价':'选物流 / 估价'}</button>`):''}<button onclick="closeModal()">关闭</button></div>`)}
function cancelAsk(id){if(!planner())return;showModal('取消发货需求',id,'<div class="notice warn">取消后释放订单占用，仓库将看到取消通知。已有物流估价保留为历史记录，不能继续调整或执行。</div><label for="cancelReason">取消原因 *</label><textarea id="cancelReason"></textarea><p id="error" class="err" role="alert"></p>',`<button onclick="detail('${id}')">返回</button><button class="danger" onclick="cancelPlan('${id}')">确认取消</button>`)}
function cancelPlan(id){if(!planner())return;let reason=$('cancelReason').value.trim();if(!reason){$('error').textContent='请填写取消原因。';return}let p=state.plans.find(p=>p.id===id);p.status='cancelled';p.logs.push(fmt(now())+' · 计划部取消需求：'+reason);p.orderIds.forEach(id=>state.orders.find(o=>o.id===id).status='ready');save();closeModal();render();toast('计划已取消，仓库可查看取消通知')}

// 发货状态独立于计划、估价状态；仓库登记整计划全部发货。
let shippingFilter='all';
function hasShipped(p){return !!p.shipment}
function shippingLabel(p){return hasShipped(p)?'已发货':'未发货'}
function setShippingFilter(v){shippingFilter=v;render()}
const shippingBaseGo=go;
go=function(v){shippingFilter='all';shippingBaseGo(v)};
const shippingBaseWarning=warning;
warning=function(p){return hasShipped(p)?{t:'已发货 · 待签收',c:'good'}:shippingBaseWarning(p)};
const shippingBasePlansView=plansView;
plansView=function(){let host=document.createElement('div');host.innerHTML=shippingBasePlansView();let filters=host.querySelector('.filters');let select=document.createElement('select');select.setAttribute('aria-label','筛选发货状态');select.setAttribute('onchange','setShippingFilter(this.value)');select.innerHTML=[['all','全部发货状态'],['unshipped','未发货'],['shipped','已发货']].map(([v,t])=>`<option value="${v}" ${shippingFilter===v?'selected':''}>${t}</option>`).join('');filters.append(select);let table=host.querySelector('table'),th=document.createElement('th');th.textContent='发货状态 / 时间';table.querySelector('thead tr').insertBefore(th,table.querySelector('thead tr').lastElementChild);let count=0;table.querySelectorAll('tbody tr').forEach(tr=>{let link=tr.querySelector('button[onclick^="detail"]');if(!link){tr.remove();return}let id=link.getAttribute('onclick').match(/detail\('([^']+)'\)/)[1],p=state.plans.find(p=>p.id===id);if(shippingFilter==='shipped'&&!hasShipped(p)||shippingFilter==='unshipped'&&hasShipped(p)){tr.remove();return}count++;let cell=document.createElement('td');cell.className='nowrap';cell.innerHTML=badge(shippingLabel(p),hasShipped(p)?'good':'')+(hasShipped(p)?`<small>实际发货 ${fmt(p.shipment.shippedAt)}</small><small>${esc(p.shipment.waybill||'未填写物流单号')}</small>`:`<small>${p.status==='draft'?'草稿，尚未下达':p.status==='cancelled'?'计划已取消':'等待计划部登记发货'}</small>`);tr.insertBefore(cell,tr.lastElementChild);let actions=tr.lastElementChild;if(hasShipped(p)){actions.querySelectorAll('button').forEach(b=>{if(!b.getAttribute('onclick').startsWith('detail'))b.remove()});let record=document.createElement('button');record.className='link';record.textContent='查看发货记录';record.setAttribute('onclick',`shipmentDetail('${id}')`);actions.append(record)}else if(warehouse()&&p.status==='published'&&activeQuote(p)){let b=document.createElement('button');b.className='primary';b.textContent='登记发货';b.setAttribute('onclick',`registerShipment('${id}')`);actions.prepend(b);actions.querySelector('button[onclick^="startEstimate"]')?.classList.replace('primary','link')}});if(!count)table.querySelector('tbody').innerHTML='<tr><td colspan="7" class="empty">没有符合条件的计划。可切换发货状态或清除筛选。<br><button onclick="clearShipmentFilters()">清除筛选</button></td></tr>';host.querySelector('.panelhead > small').textContent='共 '+count+' 个计划';let all=state.plans.filter(p=>(planner()||p.publishedAt)&&p.status==='published'),summary=document.createElement('div');summary.className='row section';summary.innerHTML=`<button class="${shippingFilter==='all'?'primary':''}" onclick="setShippingFilter('all')">全部发货状态</button><button class="${shippingFilter==='unshipped'?'primary':''}" onclick="setShippingFilter('unshipped')">未发货 ${all.filter(p=>!hasShipped(p)).length}</button><button class="${shippingFilter==='shipped'?'primary':''}" onclick="setShippingFilter('shipped')">已发货 ${all.filter(hasShipped).length}</button><small>仓库登记后，计划部和仓库均可查询历史已发货计划；已发货不代表已签收。</small>`;host.querySelector('.panel').before(summary);return host.innerHTML};
function clearShipmentFilters(){shippingFilter='all';searchText='';filter='all';render()}
const shippingBaseDetail=detail;
