function shipmentSummary(p){let s=p.shipment;return `<div class="grid"><div><p>实际发货时间：${fmt(s.shippedAt)}<br>承运物流：${esc(s.courier)}<br>物流单号：${esc(s.waybill||'未填写')}<br>登记人：${esc(s.createdBy)}<br>登记时间：${fmt(s.recordedAt)}</p></div><div><p>本计划全部发货：${s.totalQty}件，${s.boxes}箱<br>对应需求版本：V${s.planVersion}<br>发货备注：${esc(s.note||'无')}</p><small>本次为计划部人工登记。已发货不等于已签收，物流估价不等于实际结算费用。</small></div></div>`}
function shipmentDetail(id){let p=state.plans.find(p=>p.id===id);if(!p||!hasShipped(p)||warehouse()&&!p.publishedAt)return;showModal('发货记录 · '+id,'整计划全部发货 · 历史记录',shipmentSummary(p),`<button onclick="detail('${id}')">返回计划详情</button><button onclick="closeModal()">关闭</button>`)}
function registerShipment(id){if(!planner())return;let p=state.plans.find(p=>p.id===id);if(!p||p.status!=='published'||hasShipped(p)||!activeQuote(p)){toast('请先完成物流估价，且计划必须尚未发货。');return}let local=new Date(now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);showModal('登记计划发货 · '+id,'由计划部登记整计划全部发货，登记后保留历史记录',`<div class="notice">${esc(p.customer)} · ${esc(activeQuote(p).name)}<br>商品共${p.orderIds.reduce((n,id)=>n+state.orders.find(o=>o.id===id).items.reduce((s,i)=>s+i.qty,0),0)}件 · ${p.estimate.package.boxes}箱<br>本操作只登记发货结果，不调用物流接口。若本次仅发出部分商品，请勿登记为全部发货。</div><div class="grid section"><div class="field"><label for="actualShipTime">实际发货时间 *</label><input id="actualShipTime" type="datetime-local" max="${local}" value="${local}"></div><div class="field"><label for="waybill">物流单号（可选）</label><input id="waybill" maxlength="100" placeholder="填写承运商运单号"></div></div><label for="shipNote">发货备注</label><textarea id="shipNote" rows="2" placeholder="填写交接或发货说明"></textarea><label class="check" style="margin-top:16px"><input id="shipAll" type="checkbox">确认该计划内全部商品已经发货</label><p id="shipmentError" class="err" role="alert"></p>`,`<button onclick="detail('${id}')">返回</button><button class="primary" onclick="confirmShipment('${id}',${p.version})">确认登记已发货</button>`)}
function confirmShipment(id,version){if(!planner())return;let p=state.plans.find(p=>p.id===id),error=$('shipmentError');if(!p||p.version!==version||p.status!=='published'||hasShipped(p)||!activeQuote(p)){error.textContent='计划已更新、取消或已发货，请重新查看最新状态。';return}let time=new Date($('actualShipTime').value).getTime();if(!Number.isFinite(time)||time>now()){error.textContent='请填写有效的实际发货时间，且不能晚于当前时间。';return}if(time<(p.publishedAt||p.created)-60000){error.textContent='实际发货时间不能早于该计划下达时间。';return}if(!$('shipAll').checked){error.textContent='请确认本计划全部商品已经发货。';return}p.shipment={shippedAt:time,recordedAt:now(),createdBy:'计划部 · 张敏',courier:activeQuote(p).name,waybill:$('waybill').value.trim(),note:$('shipNote').value.trim(),planVersion:p.version,boxes:p.estimate.package.boxes,totalQty:p.orderIds.reduce((n,id)=>n+state.orders.find(o=>o.id===id).items.reduce((s,i)=>s+i.qty,0),0),quoteSnapshot:JSON.parse(JSON.stringify(activeQuote(p)))};p.logs.push(fmt(now())+' · 计划部登记整计划全部发货，实际发货 '+fmt(time));p.orderIds.forEach(id=>state.orders.find(o=>o.id===id).status='shipped');save();closeModal();render();toast('已登记发货，可通过“已发货”筛选查看历史计划');detail(id)}
// 发货后冻结需求与估价，避免历史发货单被修改或取消。
