const planningResultsEstimateStatus=estimateStatus;
estimateStatus=function(p){if(p.status==='draft')return'方案草稿';let label=planningResultsEstimateStatus(p);return{'待选物流':'待完善方案','需重新估价':'方案待更新','估价草稿':'方案待完善','已估价':'方案已确认'}[label]||label};
function render(){migrateWorkflow();migratePlannerResults();if(warehouse())page='plans';document.querySelectorAll('.nav').forEach(n=>{n.hidden=warehouse()&&n.id!=='nav-plans';n.classList.toggle('active',n.id==='nav-'+page)});document.querySelector('.planner').hidden=warehouse();$('role').value=role;$('crumb').textContent=(planner()?'计划部':'仓库')+' / '+{plans:planner()?'计划与发货方案':'发货计划结果',orders:'订单拆合单',rules:'物流计费规则'}[page];$('app').innerHTML=page==='plans'?plansView():page==='orders'?ordersView():rulesView()}
function go(v){if(warehouse()&&v!=='plans')return;page=v;searchText='';filter='all';shippingFilter='all';selected.clear();render()}
const resultsBasePlansView=plansView;
plansView=function(){let host=document.createElement('div');host.innerHTML=resultsBasePlansView();host.querySelector('h1').textContent=planner()?'计划与发货方案':'发货计划结果';host.querySelector('.title .muted').textContent=planner()?'计划部填写需求、选择物流、估算费用，完成后下达结果给仓库。':'查看计划部下达的最终方案、物流费用和发货状态，无需选择物流或填写价格。';let all=state.plans.filter(p=>planner()||p.publishedAt),pub=all.filter(p=>p.status==='published'),stats=planner()?[['方案草稿',all.filter(p=>p.status==='draft').length,'完善需求、物流与费用'],['待发货',pub.filter(p=>!hasShipped(p)).length,'计划部维护发货状态'],['已发货',pub.filter(hasShipped).length,'保留历史发货记录'],['时效需跟进',pub.filter(p=>!hasShipped(p)&&['bad','warn'].includes(warning(p).c)).length,'关注到货要求与发货截止']]:[['已下达结果',pub.length,'物流方案和费用已确定'],['未发货',pub.filter(p=>!hasShipped(p)).length,'查看计划部安排'],['已发货',pub.filter(hasShipped).length,'可筛选查询历史'],['更新待查看',pub.filter(p=>readLabel(p)!=='已查看').length,'打开详情记录已查看']];host.querySelector('.cards').innerHTML=stats.map(([t,n,s])=>`<div class="card"><small>${t}</small><div class="stat">${n}</div><small>${s}</small></div>`).join('');host.querySelector('.notice').innerHTML=planner()?'<b>计划部完成方案 → 下达结果 → 仓库知悉</b><br>商品、收货与时效、包裹、物流选择和预估费用由计划部统一维护；草稿不向仓库展示。':'<b>仓库仅查看计划结果</b><br>物流、预估费用及发货状态由计划部维护。可查看详情、筛选已发货计划和导出，无需填写或确认方案。';let filterEl=host.querySelector('select[aria-label="筛选计划"]');if(filterEl){filterEl.querySelector('option[value="pending"]')?.remove();let done=filterEl.querySelector('option[value="done"]');if(done)done.textContent='方案已确认'}let headers=host.querySelectorAll('thead th');headers[3].textContent='选定物流 / 预估费用';headers[4].textContent='计划 / 方案状态';host.querySelectorAll('tbody tr').forEach(tr=>{let b=tr.querySelector('button[onclick^="detail"]');if(!b)return;let id=b.getAttribute('onclick').match(/detail\('([^']+)'\)/)[1],p=state.plans.find(x=>x.id===id),q=activeQuote(p),s=estimateStatus(p);tr.children[3].innerHTML=`${q?esc(q.name):'待计划部完善'}<small><b>${q?money(q.total):'方案草稿'}</b></small>${q?'<small>制定人 '+esc(p.estimate.createdBy)+'</small>':''}`;tr.children[4].innerHTML=badge(p.status==='draft'?'草稿':p.status==='cancelled'?'已取消':'已下达',p.status==='published'?'good':'')+'<small>'+esc(p.status==='draft'?'仓库不可见':s)+'</small>'+(p.status==='published'?'<small>'+badge(readLabel(p),readLabel(p)==='已查看'?'good':'warn')+'</small>':'');tr.lastElementChild.innerHTML=`${planner()&&p.status==='published'&&!hasShipped(p)&&q?`<button class="primary" onclick="registerShipment('${id}')">登记发货</button>`:''}<button class="link" onclick="detail('${id}')">${warehouse()?'查看结果':'查看详情'}</button>${planner()&&p.status!=='cancelled'&&!hasShipped(p)?`<button class="${p.status==='draft'?'primary':'link'}" onclick="editPlan('${id}')">${p.status==='draft'?'继续完善':'修改方案'}</button>`:''}${hasShipped(p)?`<button class="link" onclick="shipmentDetail('${id}')">查看发货记录</button>`:''}`});let small=host.querySelector('.row.section small');if(small)small.textContent='计划部登记发货后，两部门均可查询历史；已发货不代表已签收。';host.querySelector('.footer').textContent='计划部统一维护需求、物流方案和发货状态 · 仓库只读查看 · 按当前筛选结果导出Excel';return host.innerHTML};
const plannerDemandWizard=showWizard,plannerQuoteWizard=showEstimate;
function startPlan(){if(!planner())return;wizard={mode:'plan',step:1,orderIds:[...selected].filter(id=>state.orders.find(o=>o.id===id)?.status==='ready'),warehouse:false,warehouseName:'',payer:'公司承担',note:'',plannedShip:'',weight:20,boxes:10,length:50,width:40,height:30,product:'',manualTotal:'',manualHours:'',manualSource:'',reason:'',riskAck:false};showWizard()}
showWizard=function(){if(!planner()||wizard?.mode!=='plan')return;let step=wizard.step;if(step<=2){plannerDemandWizard();if(step===2){let message=[...$('modalBody').querySelectorAll('.notice')].find(el=>el.textContent.includes('无需在此填写'));if(message)message.textContent='下一步由计划部选择物流并确认预估费用，完成后将整套结果下达给仓库。';let section=document.createElement('div');section.className='section';section.innerHTML='<h3>包裹信息</h3><p class="muted">按每票同规格多箱估算，用于比较不同物流体积重及费用。</p><div class="grid three">'+[['weight','单箱毛重（kg）'],['boxes','箱数'],['length','单箱长（cm）'],['width','单箱宽（cm）'],['height','单箱高（cm）']].map(([k,t])=>`<div class="field"><label for="${k}">${t} *</label><input id="${k}" type="number" min="0.1" step="${k==='boxes'?1:.1}" value="${wizard[k]}" oninput="wizard.${k}=Number(this.value);invalidate()"></div>`).join('')+'</div>';$('modalBody').querySelector('#error').before(section)}}else{wizard.step=step-1;plannerQuoteWizard();wizard.step=step;let body=$('modalBody');body.innerHTML=body.innerHTML.replaceAll('仓库选择物流并估算价格','计划部选择物流并估算价格').replaceAll('由仓库补充','由计划部补充').replaceAll('已反馈计划部并确认后续安排','已与客户确认并安排跟进').replaceAll('保存后计划部可查看物流与预估费用','下达后仓库可查看完整方案与预估费用').replaceAll('仓库选定物流','计划部选定物流').replaceAll('本次仅保存物流方案与预估费用，不改变计划部商品、数量、地址和到货要求；不代表已实际发货。','本次下达完整发货方案，仓库只查看结果；不代表已实际发货。').replaceAll('也可保存估价草稿','也可保存计划草稿');if(step===4){let request=document.createElement('div');request.innerHTML=requestSummary(wizard);body.querySelector('#error').before(request)}}$('modalTitle').textContent=wizard.editId?'修改计划与发货方案':'新建计划与发货方案';$('modalSub').textContent='计划部：填写需求 → 选择物流及估价 → 下达结果给仓库';$('modalBody').querySelector('.steps').innerHTML=['选择订单','需求与包裹','物流与费用','确认下达'].map((s,i)=>`<span class="${step===i+1?'active':''}">${i+1}. ${s}</span>`).join('');$('modalFoot').innerHTML=`<button onclick="${step===1?'closeModal()':'previousStep()'}">${step===1?'取消':'上一步'}</button><div class="row">${step>1&&!wizard.editingPublished?'<button onclick="saveDraft()">保存草稿</button>':''}<button class="primary" onclick="${step===4?'publishPlan()':'nextStep()'}">${step===4?wizard.editingPublished?'下达更新结果':'下达结果给仓库':'下一步'}</button></div>`};
selectProduct=function(id){if(!planner()||wizard?.mode!=='plan')return;wizard.product=id;wizard.manualTotal='';wizard.manualHours='';wizard.manualSource='';wizard.reason='';wizard.riskAck=false;showWizard()};
const plannerDemandValidation=validStep;
validStep=function(){if(wizard.step<=2){if(!plannerDemandValidation())return false;if(wizard.step===2&&(['weight','boxes','length','width','height'].some(k=>!Number.isFinite(wizard[k])||wizard[k]<=0)||!Number.isInteger(wizard.boxes))){$('error').textContent='重量和尺寸须大于0，箱数须为正整数。';return false}return true}let qs=quoteProducts(wizard),q=qs.find(x=>x.id===wizard.product),best=qs.find(x=>x.ready&&x.onTime),err='';if(!q?.ready)err='物流报价或时效待确认，请补齐计费口径或有依据的人工核价。';else if(!q.onTime&&!wizard.riskAck)err='存在晚到风险，请确认后续安排。';else if((q.manual||q.id!==best?.id)&&!wizard.reason.trim())err='请填写人工核价或选择非推荐物流的说明。';if(err){$('error').textContent=err;return false}return true};
nextStep=function(){if(!planner()||wizard?.mode!=='plan'||!validStep())return;if(wizard.step===1)adopt();wizard.step++;showWizard()};
function persistPlan(status){if(!planner()||wizard?.mode!=='plan')return;let old=state.plans.find(p=>p.id===wizard.editId);if(old&&hasShipped(old)){toast('已发货计划不可修改');return}let q=wizard.product?quoteProducts(wizard).find(q=>q.id===wizard.product):null;if(status==='published'&&!q?.ready)return;let id=old?.id||'PL-'+new Date().toLocaleDateString('sv-SE').replaceAll('-','')+'-'+String(state.seq++).padStart(3,'0'),version=old?old.version+(status==='published'&&old.publishedAt?1:0):1;let estimate=q?{status:status==='published'?'confirmed':'draft',planVersion:version,createdBy:'计划部 · 张敏',updatedAt:now(),package:Object.fromEntries(['weight','boxes','length','width','height'].map(k=>[k,wizard[k]])),product:wizard.product,quote:JSON.parse(JSON.stringify(q)),manualTotal:wizard.manualTotal,manualHours:wizard.manualHours,manualSource:wizard.manualSource,reason:wizard.reason,riskAck:wizard.riskAck,configSnapshot:JSON.parse(JSON.stringify(state.config))}:null;let p={id,orderIds:[...wizard.orderIds],customer:wizard.customer,temp:wizard.temp,city:wizard.city,district:wizard.district,address:wizard.address,due:wizard.due,warehouse:wizard.warehouse,warehouseName:wizard.warehouseName,payer:wizard.payer,note:wizard.note,plannedShip:wizard.plannedShip,status,version,createdBy:old?.createdBy||'计划部 · 张敏',created:old?.created||now(),publishedAt:status==='published'?now():null,viewedVersion:old?.viewedVersion,viewedAt:old?.viewedAt,estimate,estimateHistory:[...(old?.estimateHistory||[]),...(old?.estimate?[JSON.parse(JSON.stringify(old.estimate))]:[])],shipment:old?.shipment||null,logs:[...(old?.logs||[]),fmt(now())+' · 计划部'+(status==='published'?'下达完整方案 V'+version+'，物流'+q.name+'，预估费用'+money(q.total):'保存计划草稿')]};if(old){old.orderIds.filter(id=>!p.orderIds.includes(id)).forEach(id=>state.orders.find(o=>o.id===id).status='ready');state.plans[state.plans.indexOf(old)]=p}else state.plans.unshift(p);p.orderIds.forEach(id=>state.orders.find(o=>o.id===id).status='occupied');save();selected.clear();page='plans';closeModal();render();return p}
saveDraft=function(){if(!planner()||wizard?.mode!=='plan'||wizard.editingPublished)return;if(wizard.step===2&&!validStep())return;adopt();persistPlan('draft');toast('计划草稿已保存，仓库不可见')};
publishPlan=function(){if(!planner()||wizard?.mode!=='plan'||wizard.step!==4)return;if(!validStep()){wizard.step=3;showWizard();$('error').textContent='请重新确认报价和时效。';return}let p=persistPlan('published');if(p){detail(p.id);toast('完整发货方案已下达，仓库可查看结果')}};
editPlan=function(id){if(!planner())return;let p=state.plans.find(p=>p.id===id);if(!p||p.status==='cancelled'||hasShipped(p))return;let e=p.estimate;wizard={...JSON.parse(JSON.stringify(p)),...(e?.package||p.packageSeed||{weight:20,boxes:10,length:50,width:40,height:30}),mode:'plan',step:2,editId:id,editingPublished:!!p.publishedAt,product:e?.product||'',manualTotal:e?.manualTotal||'',manualHours:e?.manualHours||'',manualSource:e?.manualSource||'',reason:e?.reason||'',riskAck:false};showWizard()};
// 不再提供仓库写操作，即使从旧页面入口调用也拒绝。
startEstimate=function(){toast('物流与费用由计划部统一制定，仓库只查看结果')};saveEstimate=function(){toast('仓库无需录入物流或估价')};
detail=function(id){let p=state.plans.find(p=>p.id===id);if(!p||warehouse()&&!p.publishedAt)return;if(warehouse()&&p.status==='published'&&p.viewedVersion!==p.version){p.viewedVersion=p.version;p.viewedAt=now();p.logs.push(fmt(now())+' · 仓库查看结果 V'+p.version);save();render()}let e=p.estimate,q=activeQuote(p),w=warning(p),logistics=q?`<div class="grid section"><div class="card"><h3>最终物流方案</h3><p>${esc(q.name)}<br>${e.package.boxes}箱，总实际重${(e.package.weight*e.package.boxes).toFixed(2)}kg<br>计费重${q.bill.toFixed(2)}kg，体积重系数${q.divisor}<br>方案制定人：${esc(e.createdBy)}<br>选择说明：${esc(e.reason||'符合时效的可比报价最低')}</p></div><div class="card"><h3>预估费用 ${money(q.total)}</h3>${q.rows.map(([k,v])=>`<p>${esc(k)}：${esc(v)}</p>`).join('')}<small>${q.manual?'人工确认总价，分项仅作参考。':'按方案保存时规则估算。'}<br>运输时长${q.transit}小时 · 最晚发货${fmt(cutoff(p))}<br>来源：${esc(q.source)}</small></div></div>`:'<div class="notice warn">方案尚未完成，需计划部完善物流、时效和费用后下达；仓库不可见。</div>';showModal('计划结果 · '+id,(planner()?'计划部维护完整方案':'仓库只读查看结果')+' · V'+p.version,`<div class="notice ${p.status==='cancelled'?'bad':w.c==='bad'?'bad':''}">${p.status==='cancelled'?'计划已取消，请勿按此方案安排。':w.t+' · 客户要求到货 '+fmt(p.due)}<br>计划部下达人：${esc(p.createdBy)} · 下达${fmt(p.publishedAt)} · ${readLabel(p)}</div><div class="card section"><h3>发货状态 ${badge(shippingLabel(p),hasShipped(p)?'good':'')}</h3>${hasShipped(p)?shipmentSummary(p):'<p>尚未登记发货，状态由计划部维护。</p>'}</div>${requestSummary(p)}${logistics}<div class="card"><h3>下达与查看记录</h3><div class="timeline">${p.logs.map(s=>'<p>'+esc(s)+'</p>').join('')}</div></div>`,`<div>${planner()&&p.status!=='cancelled'&&!hasShipped(p)?`<button class="danger" onclick="cancelAsk('${id}')">取消计划</button>`:''}</div><div class="row">${planner()&&p.status!=='cancelled'&&!hasShipped(p)?`${q?`<button class="primary" onclick="registerShipment('${id}')">登记发货</button>`:''}<button onclick="editPlan('${id}')">${p.status==='draft'?'继续完善':'修改方案'}</button>`:''}<button onclick="closeModal()">关闭</button></div>`)};

// 计划部批量选择：跨页保留选中，预览分组后创建计划草稿。
let orderPage=1,orderPageSize=20,orderStatusFilter='ready',orderTempFilter='all',orderDateFrom='',orderDateTo='',onlySelectedOrders=false,wizardOrderSearch='',batchDraftSession=null;
function eligibleSelection(){return state.orders.filter(o=>selected.has(o.id)&&o.status==='ready')}
function filteredBatchOrders(){let from=orderDateFrom?new Date(orderDateFrom+'T00:00:00').getTime():null,to=orderDateTo?new Date(orderDateTo+'T00:00:00').getTime()+24*H:null;return state.orders.filter(o=>(o.id+o.source+o.customer+o.city+o.district+o.address).toLowerCase().includes(searchText.toLowerCase())&&(orderStatusFilter==='all'||o.status===orderStatusFilter)&&(orderTempFilter==='all'||o.temp===orderTempFilter)&&(!from||o.created>=from)&&(!to||o.created<to)&&(!onlySelectedOrders||selected.has(o.id))).sort((a,b)=>a.due-b.due||a.id.localeCompare(b.id))}
function batchOrderPageRows(){let rows=filteredBatchOrders(),max=Math.max(1,Math.ceil(rows.length/orderPageSize));orderPage=Math.min(Math.max(orderPage,1),max);return rows.slice((orderPage-1)*orderPageSize,orderPage*orderPageSize)}
ordersView=function(){let all=filteredBatchOrders(),rows=batchOrderPageRows(),ready=all.filter(o=>o.status==='ready'),chosen=eligibleSelection(),pages=Math.max(1,Math.ceil(all.length/orderPageSize));return `<div class="between title"><div><h1>订单选择与批量建计划</h1><div class="muted">按下单日期、客户及温层筛选，跨页勾选后批量生成计划草稿，再完善物流并下达。</div></div><button onclick="startPlan()">创建单个计划</button></div><div class="notice"><b>支持本页全选、全部筛选结果选择和跨页保留。</b><br>仅“待计划”订单可选；已占用、已拆合或已发货订单不可重复建计划。不同收货地址、客户或温层自动分开。</div><div class="panel"><div class="panelhead"><div class="row filters"><input aria-label="搜索订单" placeholder="搜索订单 / 客户 / 收货地址" value="${esc(searchText)}" oninput="setBatchSearch(this.value)"><select aria-label="订单状态筛选" onchange="setBatchOrderFilter('status',this.value)">${[['ready','待计划'],['all','全部订单状态'],['occupied','已占用'],['processed','已拆合'],['shipped','已发货']].map(([v,t])=>`<option value="${v}" ${orderStatusFilter===v?'selected':''}>${t}</option>`).join('')}</select><select aria-label="订单温层筛选" onchange="setBatchOrderFilter('temp',this.value)">${[['all','全部温层'],['normal','常温'],['cold','冷运']].map(([v,t])=>`<option value="${v}" ${orderTempFilter===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="row" style="margin-top:12px"><label for="orderDateFrom" style="margin:0">下单日期</label><input id="orderDateFrom" type="date" style="width:160px" value="${orderDateFrom}" onchange="setBatchOrderFilter('from',this.value)"><span>至</span><input aria-label="下单结束日期" type="date" style="width:160px" value="${orderDateTo}" onchange="setBatchOrderFilter('to',this.value)"><button onclick="clearBatchOrderFilters()">清除筛选</button><label class="check" style="margin:0"><input type="checkbox" ${onlySelectedOrders?'checked':''} onchange="setBatchOrderFilter('selected',this.checked)">仅看已选</label></div></div><div class="between panelhead"><div class="row"><b>已选 ${chosen.length} 单</b><small>跨页及筛选切换后保留</small><button ${ready.length?'':'disabled'} onclick="selectAllFilteredOrders()">选择全部筛选结果（${ready.length}单）</button><button ${chosen.length?'':'disabled'} onclick="clearBatchSelection()">清空已选</button></div><button class="primary" ${chosen.length?'':'disabled'} onclick="previewBatchPlans([...selected])">批量创建计划（${chosen.length}）</button></div><div class="tablewrap"><table><thead><tr><th><input id="selectOrderPage" type="checkbox" aria-label="全选本页待计划订单" onchange="selectOrderPage(this.checked)" ${rows.some(o=>o.status==='ready')?'':'disabled'}></th><th>订单 / 来源</th><th>客户 / 收货地址</th><th>商品 / 温层</th><th>下单 / 要求到货</th><th>状态</th></tr></thead><tbody>${rows.map(o=>`<tr><td><input type="checkbox" aria-label="选择 ${o.id}" ${o.status!=='ready'?'disabled':''} ${selected.has(o.id)?'checked':''} onchange="pick('${o.id}',this.checked)"></td><td class="nowrap"><b>${esc(o.id)}</b><small>${esc(o.source)}</small></td><td>${esc(o.customer)}<small>${esc(o.city+o.district+o.address)}</small></td><td>${badge(o.temp==='cold'?'冷运':'常温')}<small>${o.items.map(i=>esc(i.name)+'×'+i.qty).join('；')}</small></td><td class="nowrap">${fmt(o.created)}<small>要求到货 ${fmt(o.due)}</small><small>${countdown(o.due)}</small></td><td>${badge({ready:'待计划',occupied:'已占用',processed:'已拆合',shipped:'已发货'}[o.status],o.status==='ready'?'good':'')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">没有符合筛选条件的订单。<br><button onclick="clearBatchOrderFilters()">清除筛选</button></td></tr>'}</tbody></table></div><div class="between footer"><div class="row"><span>共${all.length}单，第${orderPage}/${pages}页</span><select aria-label="每页订单数" style="width:125px" onchange="orderPageSize=Number(this.value);orderPage=1;render()">${[20,50,100].map(n=>`<option ${orderPageSize===n?'selected':''}>${n}</option>`).join('')}</select><button ${orderPage===1?'disabled':''} onclick="orderPage--;render()">上一页</button><button ${orderPage===pages?'disabled':''} onclick="orderPage++;render()">下一页</button></div><div class="row"><button ${chosen.length<2?'disabled':''} onclick="mergeOrders()">合并订单</button><button ${chosen.length!==1?'disabled':''} onclick="splitOrder()">拆分订单</button></div></div></div>`};
function setBatchSearch(v){orderPage=1;setSearch(v)}
function setBatchOrderFilter(k,v){if(k==='status')orderStatusFilter=v;else if(k==='temp')orderTempFilter=v;else if(k==='from')orderDateFrom=v;else if(k==='to')orderDateTo=v;else if(k==='selected')onlySelectedOrders=v;orderPage=1;render()}
function clearBatchOrderFilters(){searchText='';orderStatusFilter='ready';orderTempFilter='all';orderDateFrom='';orderDateTo='';onlySelectedOrders=false;orderPage=1;render()}
function clearBatchSelection(){selected.clear();render()}
pick=function(id,v){let o=state.orders.find(o=>o.id===id);if(!planner()||!o||o.status!=='ready')return;v?selected.add(id):selected.delete(id);render()};
function selectOrderPage(v){if(!planner())return;batchOrderPageRows().filter(o=>o.status==='ready').forEach(o=>v?selected.add(o.id):selected.delete(o.id));render()}
function selectAllFilteredOrders(){if(!planner())return;filteredBatchOrders().filter(o=>o.status==='ready').forEach(o=>selected.add(o.id));render()}
const batchBaseRender=render;
render=function(){selected=new Set([...selected].filter(id=>state.orders.some(o=>o.id===id&&o.status==='ready')));batchBaseRender();if(planner()&&page==='orders'){let box=$('selectOrderPage'),list=batchOrderPageRows().filter(o=>o.status==='ready'),count=list.filter(o=>selected.has(o.id)).length;if(box){box.checked=!!list.length&&count===list.length;box.indeterminate=count>0&&count<list.length}}};
function batchGroupKey(o){return JSON.stringify([o.customer,o.phone,o.city,o.district,o.address,o.temp,o.originWarehouse||'马鞍山市主仓',!!o.warehouse,o.warehouseName||'',o.payer||'公司承担',o.note||'',o.plannedShip||''])}
function batchGroups(ids,strategy){let list=ids.map(id=>state.orders.find(o=>o.id===id)).filter(o=>o&&o.status==='ready'),map=new Map();for(let o of list){let key=strategy==='perOrder'?o.id:batchGroupKey(o);if(!map.has(key))map.set(key,[]);map.get(key).push(o)}return [...map.values()].map(list=>({ids:list.map(o=>o.id),customer:list[0].customer,city:list[0].city,district:list[0].district,address:list[0].address,temp:list[0].temp,due:Math.min(...list.map(o=>o.due)),created:Math.min(...list.map(o=>o.created)),qty:list.reduce((n,o)=>n+o.items.reduce((s,i)=>s+i.qty,0),0),snapshot:JSON.stringify(list)}))}
function previewBatchPlans(ids){if(!planner())return;ids=[...new Set(ids)].filter(id=>state.orders.some(o=>o.id===id&&o.status==='ready'));if(!ids.length){toast('请先选择待计划订单');return}batchDraftSession={ids,strategy:'compatible',completed:false};showBatchPreview()}
function showBatchPreview(){if(!planner()||!batchDraftSession||batchDraftSession.completed)return;let job=batchDraftSession,groups=batchGroups(job.ids,job.strategy);job.groups=groups;showModal('批量创建发货计划','先预览分组，再批量生成草稿；原始订单及数量保持不变',`<div class="notice"><b>已选择${job.ids.length}单，预计生成${groups.length}个计划草稿。</b><br>只创建草稿，不立即下达给仓库。后续由计划部完善各计划的物流与费用，确认后下达最终结果。</div><div class="section"><label for="batchStrategy">创建方式</label><select id="batchStrategy" onchange="batchDraftSession.strategy=this.value;showBatchPreview()"><option value="compatible" ${job.strategy==='compatible'?'selected':''}>相同客户、地址、温层及发货要求归为一个计划</option><option value="perOrder" ${job.strategy==='perOrder'?'selected':''}>每个订单分别创建一个计划</option></select><small>归组时同时核对收货电话、发货仓、入仓要求及其他配送要求；到货时间取组内最早值。</small></div><div class="tablewrap"><table><thead><tr><th>计划分组</th><th>客户 / 地址</th><th>订单 / 商品总量</th><th>温层 / 最早到货</th></tr></thead><tbody>${groups.map((g,i)=>`<tr><td>第${i+1}组</td><td>${esc(g.customer)}<small>${esc(g.city+g.district+g.address)}</small></td><td>${g.ids.map(esc).join(' / ')}<small>${g.ids.length}单 / ${g.qty}件</small></td><td>${badge(g.temp==='cold'?'冷运':'常温')}<small>${fmt(g.due)}</small></td></tr>`).join('')}</tbody></table></div><p id="batchError" class="err" role="alert"></p>`,`<button onclick="closeModal()">返回调整选择</button><button class="primary" ${groups.length?'':'disabled'} onclick="confirmBatchPlans()">生成${groups.length}个计划草稿</button>`)}
function confirmBatchPlans(){if(!planner()||!batchDraftSession||batchDraftSession.completed)return;let job=batchDraftSession,created=[],skipped=[];job.completed=true;for(let g of job.groups){let orders=g.ids.map(id=>state.orders.find(o=>o.id===id));if(orders.some(o=>!o||o.status!=='ready')||JSON.stringify(orders)!==g.snapshot){skipped.push({ids:g.ids,reason:'订单已被占用或信息发生变化，请重新选择'});continue}let o=orders[0],id='PL-'+new Date().toLocaleDateString('sv-SE').replaceAll('-','')+'-'+String(state.seq++).padStart(3,'0'),p={id,orderIds:[...g.ids],customer:o.customer,temp:o.temp,city:o.city,district:o.district,address:o.address,due:g.due,warehouse:!!o.warehouse,warehouseName:o.warehouseName||'',payer:o.payer||'公司承担',note:o.note||'',plannedShip:o.plannedShip||'',status:'draft',version:1,createdBy:'计划部 · 张敏',created:now(),publishedAt:null,estimate:null,estimateHistory:[],shipment:null,batchCreated:true,logs:[fmt(now())+' · 计划部批量创建草稿，包含'+orders.length+'单；待完善物流和费用后下达']};state.plans.unshift(p);orders.forEach(o=>o.status='occupied');created.push(p);g.ids.forEach(id=>selected.delete(id))}save();page='plans';searchText='';filter='draft';shippingFilter='all';render();showModal('批量创建结果','草稿已保留，可继续完善完整发货方案',`<div class="notice ${skipped.length?'warn':''}">成功创建${created.length}个计划草稿，跳过${skipped.length}组。<br>已成功的订单不会重复创建，仓库暂不可见。</div>${created.length?`<div class="tablewrap"><table><thead><tr><th>计划编号</th><th>客户 / 订单数</th><th>后续操作</th></tr></thead><tbody>${created.map(p=>`<tr><td>${p.id}</td><td>${esc(p.customer)}<small>${p.orderIds.length}单 · ${p.temp==='cold'?'冷运':'常温'}</small></td><td><button onclick="editPlan('${p.id}')">完善物流与费用</button></td></tr>`).join('')}</tbody></table></div>`:''}${skipped.map(s=>'<p class="err">'+s.ids.map(esc).join(' / ')+'：'+esc(s.reason)+'</p>').join('')}`,`<span>可在“方案草稿”中继续处理</span><button class="primary" onclick="closeModal()">查看计划草稿</button>`)}
// 新建单个计划的订单选择页同样支持搜索和全选，或转入批量建计划。
const batchBaseShowWizard=showWizard;
showWizard=function(){batchBaseShowWizard();if(!planner()||wizard?.mode!=='plan'||wizard.step!==1||wizard.editId)return;let toolbar=document.createElement('div');toolbar.className='card section';toolbar.innerHTML=`<div class="row filters"><input id="wizardOrderQuery" aria-label="筛选可选订单" placeholder="搜索订单 / 客户 / 地址" value="${esc(wizardOrderSearch)}" oninput="filterWizardOrders(this.value)"><button onclick="selectWizardOrders()">全选当前结果</button><button onclick="wizard.orderIds=[];showWizard()">清空已选</button><button id="wizardBatchButton" onclick="previewBatchPlans(wizard.orderIds)" ${wizard.orderIds.length?'':'disabled'}>批量创建分组计划（${wizard.orderIds.length}）</button></div><small>同一客户地址可继续创建单个计划；跨客户、跨地址或大量订单可批量生成分组草稿。</small>`;$('modalBody').querySelector('.steps').after(toolbar);filterWizardOrders(wizardOrderSearch)};
function filterWizardOrders(v){wizardOrderSearch=v;let labels=[...$('modalBody').querySelectorAll('label.quote')];labels.forEach(label=>label.hidden=!label.textContent.toLowerCase().includes(v.toLowerCase()))}
function selectWizardOrders(){if(!planner()||wizard?.editId)return;let ids=[...$('modalBody').querySelectorAll('label.quote')].filter(l=>!l.hidden).map(l=>l.querySelector('input').getAttribute('onchange').match(/chooseOrder\('([^']+)'/)[1]);wizard.orderIds=[...new Set([...wizard.orderIds,...ids])];showWizard()}

render();setInterval(()=>{if(!$('modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))render()},60000);
